var singleNumber = function(nums) {
    // XOR accumulates bits; a ^ a = 0, so every duplicate cancels out
    // Only the unique number, which has no pair, will remain in result
    let result = 0;

    for (const n of nums) {
        result = result ^ n;
    }

    return result;
};
